solution.solution.cpp:
#include <algorithm>
#include <cstdint>
#include <optional>
#include <vector>

struct Version { std::uint16_t major, minor; };
struct Envelope { std::uint8_t type; std::uint8_t flags; std::uint32_t id; std::vector<std::uint8_t> payload; };

std::vector<std::uint8_t> encodeHello(Version v)
{
    return { 'X', 'I', 'P', 'C', static_cast<std::uint8_t>(v.major), static_cast<std::uint8_t>(v.major >> 8),
             static_cast<std::uint8_t>(v.minor), static_cast<std::uint8_t>(v.minor >> 8) };
}

std::optional<Version> decodeHello(const std::vector<std::uint8_t>& b)
{
    if (b.size() != 8 || b[0] != 'X' || b[1] != 'I' || b[2] != 'P' || b[3] != 'C') return std::nullopt;
    return Version{ static_cast<std::uint16_t>(b[4] | (b[5] << 8)), static_cast<std::uint16_t>(b[6] | (b[7] << 8)) };
}

std::optional<Version> negotiate(Version client, const std::vector<Version>& serverSupports)
{
    for (const Version& s : serverSupports)
        if (s.major == client.major) return Version{ s.major, std::min(s.minor, client.minor) };
    return std::nullopt;
}

std::vector<std::uint8_t> encodeEnvelope(const Envelope& e)
{
    std::vector<std::uint8_t> out{ e.type, e.flags };
    for (int i{ 0 }; i < 4; ++i) out.push_back(static_cast<std::uint8_t>(e.id >> (8 * i)));
    out.insert(out.end(), e.payload.begin(), e.payload.end());
    return out;
}

std::optional<Envelope> decodeEnvelope(const std::vector<std::uint8_t>& b)
{
    if (b.size() < 6) return std::nullopt;
    Envelope e{ b[0], b[1], 0, {} };
    for (int i{ 0 }; i < 4; ++i) e.id |= static_cast<std::uint32_t>(b[2 + i]) << (8 * i);
    e.payload.assign(b.begin() + 6, b.end());
    return e;
}

unitTests:
using Bytes = std::vector<std::uint8_t>;
TEST("hello") {
    CHECK(encodeHello({ 2, 3 }) == (Bytes{ 'X', 'I', 'P', 'C', 2, 0, 3, 0 }));
    const auto v{ decodeHello(encodeHello({ 513, 7 })) };
    CHECK(v.has_value());
    if (v) { CHECK_EQ(v->major, 513); CHECK_EQ(v->minor, 7); }
    CHECK(!decodeHello(Bytes{ 'G', 'E', 'T', ' ', '/', ' ', 'H', 'T' }).has_value());
    CHECK(!decodeHello(Bytes{ 'X', 'I', 'P', 'C', 2, 0 }).has_value());
}
TEST("negotiating versions") {
    const std::vector<Version> server{ { 1, 9 }, { 2, 1 } };
    const auto a{ negotiate({ 2, 3 }, server) };
    CHECK(a.has_value());
    if (a) { CHECK_EQ(a->major, 2); CHECK_EQ(a->minor, 1); }
    const auto b{ negotiate({ 1, 4 }, server) };
    if (b) { CHECK_EQ(b->major, 1); CHECK_EQ(b->minor, 4); }
    CHECK(b.has_value());
    CHECK(!negotiate({ 3, 0 }, server).has_value());
}
TEST("envelopes") {
    const Envelope e{ 7, 0x01, 0x01020304, { 'h', 'i' } };
    const Bytes wire{ encodeEnvelope(e) };
    CHECK(wire == (Bytes{ 7, 1, 4, 3, 2, 1, 'h', 'i' }));
    const auto back{ decodeEnvelope(wire) };
    CHECK(back.has_value());
    if (back) { CHECK_EQ(back->id, 0x01020304u); CHECK(back->payload == (Bytes{ 'h', 'i' })); }
    CHECK(decodeEnvelope(Bytes{ 1, 0, 0, 0, 0, 0 }).has_value());
    CHECK(!decodeEnvelope(Bytes{ 1, 0, 0 }).has_value());
}

